    78→// ParseHookInput parses Gemini CLI hook input from stdin.
    79→func (g *GeminiCLIAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
    80→	data, err := io.ReadAll(reader)
    81→	if err != nil {
    82→		return nil, fmt.Errorf("failed to read input: %w", err)
    83→	}
    84→
    85→	if len(data) == 0 {
    86→		return nil, errors.New("empty input")
    87→	}
    88→
    89→	input := &agent.HookInput{
    90→		HookType:  hookType,
    91→		Timestamp: time.Now(),
    92→		RawData:   make(map[string]interface{}),
    93→	}
    94→
    95→	// Parse based on hook type
    96→	switch hookType {
    97→	case agent.HookSessionStart, agent.HookStop:
    98→		var raw sessionInfoRaw
    99→		if err := json.Unmarshal(data, &raw); err != nil {
   100→			return nil, fmt.Errorf("failed to parse session info: %w", err)
   101→		}
   102→		input.SessionID = raw.SessionID
   103→		input.SessionRef = raw.TranscriptPath
   104→		// Store Gemini-specific fields in RawData
   105→		input.RawData["cwd"] = raw.Cwd
   106→		input.RawData["hook_event_name"] = raw.HookEventName
   107→		if raw.Source != "" {
   108→			input.RawData["source"] = raw.Source
   109→		}
   110→		if raw.Reason != "" {
   111→			input.RawData["reason"] = raw.Reason
   112→		}
   113→
   114→	case agent.HookUserPromptSubmit:
   115→		// BeforeAgent is Gemini's equivalent to Claude's UserPromptSubmit
   116→		// It provides the user's prompt in the "prompt" field
   117→		var raw agentHookInputRaw
   118→		if err := json.Unmarshal(data, &raw); err != nil {
   119→			return nil, fmt.Errorf("failed to parse agent hook input: %w", err)
   120→		}
   121→		input.SessionID = raw.SessionID
   122→		input.SessionRef = raw.TranscriptPath
   123→		input.RawData["cwd"] = raw.Cwd
   124→		input.RawData["hook_event_name"] = raw.HookEventName
   125→		if raw.Prompt != "" {
   126→			input.UserPrompt = raw.Prompt
   127→			input.RawData["prompt"] = raw.Prompt
   128→		}
   129→
   130→	case agent.HookPreToolUse, agent.HookPostToolUse:
   131→		var raw toolHookInputRaw
   132→		if err := json.Unmarshal(data, &raw); err != nil {
   133→			return nil, fmt.Errorf("failed to parse tool hook input: %w", err)
   134→		}
   135→		input.SessionID = raw.SessionID
   136→		input.SessionRef = raw.TranscriptPath
   137→		input.ToolName = raw.ToolName
   138→		input.ToolInput = raw.ToolInput
   139→		if hookType == agent.HookPostToolUse {
   140→			input.ToolResponse = raw.ToolResponse
   141→		}
   142→		input.RawData["cwd"] = raw.Cwd
   143→		input.RawData["hook_event_name"] = raw.HookEventName
   144→	}
   145→
   146→	return input, nil
   147→}
