   188→// ReadSession reads a session from Gemini's storage (JSON transcript file).
   189→// The session data is stored in NativeData as raw JSON bytes.
   190→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   191→	if input.SessionRef == "" {
   192→		return nil, errors.New("session reference (transcript path) is required")
   193→	}
   194→
   195→	// Read the raw JSON file
   196→	data, err := os.ReadFile(input.SessionRef)
   197→	if err != nil {
   198→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   199→	}
   200→
   201→	// Parse to extract computed fields
   202→	modifiedFiles, err := ExtractModifiedFiles(data)
   203→	if err != nil {
   204→		// Non-fatal: we can still return the session without modified files
   205→		modifiedFiles = nil
   206→	}
   207→
   208→	return &agent.AgentSession{
   209→		SessionID:     input.SessionID,
   210→		AgentName:     g.Name(),
   211→		SessionRef:    input.SessionRef,
   212→		StartTime:     time.Now(),
   213→		NativeData:    data,
   214→		ModifiedFiles: modifiedFiles,
   215→	}, nil
   216→}
