   218→// WriteSession writes a session to Gemini's storage (JSON transcript file).
   219→// Uses the NativeData field which contains raw JSON bytes.
   220→func (g *GeminiCLIAgent) WriteSession(session *agent.AgentSession) error {
   221→	if session == nil {
   222→		return errors.New("session is nil")
   223→	}
   224→
   225→	// Verify this session belongs to Gemini CLI
   226→	if session.AgentName != "" && session.AgentName != g.Name() {
   227→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
   228→	}
   229→
   230→	if session.SessionRef == "" {
   231→		return errors.New("session reference (transcript path) is required")
   232→	}
   233→
   234→	if len(session.NativeData) == 0 {
   235→		return errors.New("session has no native data to write")
   236→	}
   237→
   238→	// Write the raw JSON data
   239→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
   240→		return fmt.Errorf("failed to write transcript: %w", err)
   241→	}
   242→
   243→	return nil
   244→}
