   363→// TranscriptChunker interface implementation
   364→
   365→// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
   366→// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
   367→// the messages array while preserving the JSON structure in each chunk.
   368→func (g *GeminiCLIAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
   369→	var transcript GeminiTranscript
   370→	if err := json.Unmarshal(content, &transcript); err != nil {
   371→		// Fall back to JSONL chunking if not valid Gemini JSON
   372→		chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
   373→		if chunkErr != nil {
   374→			return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
   375→		}
   376→		return chunks, nil
   377→	}
   378→
   379→	if len(transcript.Messages) == 0 {
   380→		return [][]byte{content}, nil
   381→	}
   382→
   383→	var chunks [][]byte
   384→	var currentMessages []GeminiMessage
   385→	currentSize := len(`{"messages":[]}`) // Base JSON structure size
   386→
   387→	for i, msg := range transcript.Messages {
   388→		// Marshal message to get its size
   389→		msgBytes, err := json.Marshal(msg)
   390→		if err != nil {
   391→			logging.Warn(context.Background(), "failed to marshal Gemini message during chunking",
   392→				slog.Int("message_index", i),
   393→				slog.String("error", err.Error()),
   394→			)
   395→			continue
   396→		}
   397→		msgSize := len(msgBytes) + 1 // +1 for comma separator
   398→
   399→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
   400→			// Save current chunk
   401→			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
   402→			if err != nil {
   403→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
   404→			}
   405→			chunks = append(chunks, chunkData)
   406→
   407→			// Start new chunk
   408→			currentMessages = nil
   409→			currentSize = len(`{"messages":[]}`)
   410→		}
   411→
   412→		currentMessages = append(currentMessages, msg)
   413→		currentSize += msgSize
   414→	}
   415→
   416→	// Add the last chunk
   417→	if len(currentMessages) > 0 {
   418→		chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
   419→		if err != nil {
   420→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
   421→		}
   422→		chunks = append(chunks, chunkData)
   423→	}
   424→
   425→	return chunks, nil
   426→}
   427→
   428→// ReassembleTranscript merges Gemini JSON chunks by combining their message arrays.
   429→func (g *GeminiCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
   430→	var allMessages []GeminiMessage
   431→
   432→	for _, chunk := range chunks {
   433→		var transcript GeminiTranscript
   434→		if err := json.Unmarshal(chunk, &transcript); err != nil {
   435→			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
   436→		}
   437→		allMessages = append(allMessages, transcript.Messages...)
   438→	}
   439→
   440→	result, err := json.Marshal(GeminiTranscript{Messages: allMessages})
   441→	if err != nil {
   442→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
   443→	}
   444→	return result, nil
   445→}
