    74→// ChunkJSONL splits JSONL content at line boundaries.
    75→// This is the default chunking for agents using JSONL format (like Claude Code).
    76→func ChunkJSONL(content []byte, maxSize int) ([][]byte, error) {
    77→	lines := strings.Split(string(content), "\n")
    78→	var chunks [][]byte
    79→	var currentChunk strings.Builder
    80→
    81→	for i, line := range lines {
    82→		// Check if adding this line would exceed the chunk size
    83→		lineWithNewline := line + "\n"
    84→
    85→		// Check if a single line exceeds maxSize - this is an error since we can't split JSONL lines
    86→		if len(lineWithNewline) > maxSize {
    87→			return nil, fmt.Errorf("JSONL line %d exceeds maximum chunk size (%d bytes > %d bytes); cannot split a single JSON object", i+1, len(lineWithNewline), maxSize)
    88→		}
    89→
    90→		if currentChunk.Len()+len(lineWithNewline) > maxSize && currentChunk.Len() > 0 {
    91→			// Save current chunk and start a new one
    92→			chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
    93→			currentChunk.Reset()
    94→		}
    95→		currentChunk.WriteString(lineWithNewline)
    96→	}
    97→
    98→	// Add the last chunk if it has content
    99→	if currentChunk.Len() > 0 {
   100→		chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
   101→	}
   102→
   103→	return chunks, nil
   104→}
